import"./strings.m.js";import{assert}from"chrome://resources/js/assert.js";import{CustomElement}from"chrome://resources/js/custom_element.js";import{DlpClipboardElement}from"./dlp_clipboard_tab.js";import{getTemplate}from"./dlp_tabs.html.js";const DLP_TABS=[{title:"Clipboard",directive:DlpClipboardElement.is}];class DlpTabsElement extends CustomElement{static get is(){return"dlp-tabs"}static get template(){return getTemplate()}get tabHeaders(){return this.$all(".tabs > button")}get tabContents(){return this.$all(".content > div")}constructor(){super();const headersRoot=this.$(".tabs");const contentRoot=this.$(".content");assert(headersRoot);assert(contentRoot);for(const tab of DLP_TABS){this.addTab(headersRoot,contentRoot,tab)}window.onhashchange=()=>{this.urlHashChanged(window.location.hash)};this.urlHashChanged(window.location.hash)}urlHashChanged(hash){hash=(hash||"").split("#").pop()||"";const tab=DLP_TABS.find((t=>t.directive===hash.toLowerCase()))||DLP_TABS[0];if(tab){this.showTab(tab)}else{console.error(`Could not find tab for hash '${hash}', and no default tab was available.'`)}}onTabSelected(tabId){window.location.hash=tabId}showTab(tab){const index=DLP_TABS.findIndex((x=>x===tab));assert(index>=0);this.tabHeaders.forEach((h=>h.classList.remove("active")));this.tabHeaders.item(index).classList.add("active");this.tabContents.forEach((c=>this.hideElement(c)));this.showElement(this.tabContents.item(index))}addTab(headersRoot,contentRoot,tab){const headerElement=document.createElement("button");headerElement.innerText=tab.title;headerElement.addEventListener("click",(()=>this.onTabSelected(tab.directive)));headersRoot.appendChild(headerElement);const contentElement=document.createElement("div");contentElement.classList.add("tabcontent");contentElement.id=tab.directive;contentElement.appendChild(document.createElement(tab.directive));contentRoot.appendChild(contentElement)}showElement(element){element?.classList.remove("hidden")}hideElement(element){element?.classList.add("hidden")}}customElements.define(DlpTabsElement.is,DlpTabsElement);